\label{thm:wronskian}
For each variable $X_i$ and any $\bm{x}$, $\psi_{Y\mid\bm{X},i}(\cdot\!\mid\!\bm{x})\in\text{span}(\bm{\phi})$ implies $W_Y(s_{X_i,Y},\bm{\eta}_{Y\mid\bm{X}})=0$ for any $y$. If: \textbf{(i)} The components in $\bm{\eta}_{Y\mid\bm{X}}$ are linearly independent; \textbf{(ii)} There exists $y$ such that $W_Y(\bm{\eta}_{Y\mid\bm{X}})\ne 0$; \textbf{(iii)} For each basis function $\phi_j$, $\lim_{y\to\pm\infty}\phi_j\,p_{Y\mid\bm{X}}=0$;
then the converse is also true.

\label{cor:qpe-fcm-quantify-id}
Assume that there are $k$ basis functions in $\bm{\phi}$ and certain regularity conditions hold. Then: \textbf{(i)} $\dim(\mathbf{\Theta}_{X\to Y;\bm{\phi}})=\infty$;
\textbf{(ii)} $\dim(\mathbf{\Theta}_{X\gets Y;\bm{\phi}})\le k+2$.

\label{thm:fi-qpe}
For each covariate $X_i$, if \cref{assum:vanishing} holds then
\[\mathbb{E}\left[(\psi_{Y\mid\bm{X},i})^2\,(s_Y)^2\right]=\mathbb{E}\left[(s_{X_i})^2\right]-\mathbb{E}\left[(r_{X_i})^2\right]+\mathbb{E}\left[(\partial_{y}\psi_{Y\mid\bm{X},i})^2+2\,\psi_{Y\mid\bm{X},i}\,\partial^2_{y}\psi_{Y\mid\bm{X},i}\right].\]

\label{assum:fico_assum}
For each variable $X_i$, any of its parents $P_j\in\bm{P}_i$ satisfy \cref{assum:vanishing} and
\[\mathbb{E}\left[(\partial_{y}\psi_{X_i\mid\bm{P}_i,j})^2+2\,\psi_{X_i\mid\bm{P}_i,j}\,\partial^2_{y}\psi_{X_i\mid\bm{P}_i,j}\right]<\mathbb{E}\left[(\psi_{X_i\mid\bm{P}_i,j}-1)^2\,(s_Y)^2\right]+\mathbb{E}\left[(r_{X_i})^2\right].\]

\caption{Fisher Information Causal Ordering}
\begin{algorithmic}
   \STATE {\bfseries Input:} a set of $d$ random variables $\bm{X}$.
   \STATE {\bfseries Output:} causal order $\pi$
   \STATE $\bm{X}^{(1)}\gets\bm{X},\pi\gets[\,]$
   \FOR{$j=1$ {\bfseries to} $d$}
        \STATE $l\gets\arg\min_i\mathbb{E}\left[\left(\partial_{x_i}\log p_{\bm{X}^{(j)}}\right)^2\right]$
        \STATE $\bm{X}^{(j+1)}\gets\bm{X}^{(j)}_{-l},\pi\gets[l,\pi]$
   \ENDFOR
   \STATE {\bfseries return} $\pi$
\end{algorithmic}

